static rt_err_t k1x_dma_program_remap(void)
{
	unsigned long flags = rt_spin_lock_irqsave(&g_dma_remap_lock);

	writel(K1X_DMA_REMAP_UPPER_4G, K1X_DDR_REMAP_BASE_REG);
	rt_spin_unlock_irqrestore(&g_dma_remap_lock, flags);
	return 0;
}

static void enable_chan(struct mmp_pdma_phy *phy)
{
	rt_uint32_t reg;
	rt_uint32_t val;
	unsigned long flags;
	struct mmp_pdma_device *pdev;

	if (!phy)
		return;

	if (!phy->vchan)
		return;

	pdev = phy->vchan->device;
	flags = rt_spin_lock_irqsave(&pdev->phy_lock);

	reg = DMA_RSSR(phy->idx);
	writel(phy->vchan->dcrs, phy->base + reg);

	reg = DMA_CCR(phy->idx);
	val = readl(phy->base + reg);
	writel(val | DMA_CCR_CH_EN, phy->base + reg);

	val = readl(phy->base + DMA_DIMR);
	val &= (~BIT(phy->idx));
	writel(val, phy->base + DMA_DIMR);

	rt_spin_unlock_irqrestore(&pdev->phy_lock, flags);
}

static void disable_chan(struct mmp_pdma_phy *phy)
{
	rt_uint32_t reg;
	rt_uint32_t val;
	unsigned long flags;
	struct mmp_pdma_device *pdev;

	if (!phy)
		return;

	pdev = phy->vchan->device;
	flags = rt_spin_lock_irqsave(&pdev->phy_lock);

	reg = DMA_RSSR(phy->idx);
	writel(0, phy->base + reg);

	reg = DMA_CCR(phy->idx);
	val = readl(phy->base + reg);
	writel((val & (~DMA_CCR_CH_EN)), phy->base + reg);

	val = readl(phy->base + DMA_DIMR);
	val |= (BIT(phy->idx));
	writel(val, phy->base + DMA_DIMR);

	rt_spin_unlock_irqrestore(&pdev->phy_lock, flags);
}

