 * vendor/SpaceMiT/chips/k1-rcpu/k1r_dma.c
 *
 * SpacemiT K1 RCPU (Nuclei N308) AHBDMA 驱动 —— NuttX 通用 DMA 框架 provider。
 *
 * 实现:
 *  - struct dma_dev_s (get_chan/put_chan)
 *  - 每通道 dma_chan_s->ops (config/start/stop/pause/resume/residual)
 *  - riscv_dma_initialize()  芯片启动时初始化 (弱符号覆盖, 见 riscv_initialize.c)
 *  - k1r_dma_getdev()        供上层 (audio_dma / 自测) 拿到 dma_dev
 *
 * 关键(芯片级, 见 k1r_dma.h):
 *  - DMA 只寻址 0x4000_0000~0x4FFF_FFFF, 传输前 k1r_dma_program_remap()
 *  - DMA_DIMR 复位全屏蔽, 每笔须清对应通道位
 *  - 禁址区 0x40000~0x80000
 *
 * 参考: 手册 ch14 §15.3.4 + esOS dma_k1x.c + NuttX drivers/audio/audio_dma.c (客户端范例)
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <assert.h>
#include <debug.h>

#include <nuttx/irq.h>
#include <nuttx/dma/dma.h>
#include <nuttx/spinlock.h>

#include "hardware/k1r_dma.h"

#ifdef CONFIG_K1R_DMA

/* 每通道私有状态 (callback/arg 由 dma_chan_s 之外按 ident 索引) */
struct k1r_dma_chanpriv_s
{
  dma_callback_t callback;
  FAR void      *arg;
  bool           active;
};

struct k1r_dma_dev_s
{
  struct dma_dev_s           dev;   /* 必须首个, 用户拿到的就是它 */
  struct dma_chan_s          chan[K1R_AHBDMA_NCHAN];
  struct k1r_dma_chanpriv_s  priv[K1R_AHBDMA_NCHAN];
  spinlock_t                 lock;
  uintptr_t                  base;
};

static struct k1r_dma_dev_s g_k1r_dma;

#define K1R_GETPRIV(ch)  (&g_k1r_dma.priv[(ch)])

/* 存取 MMIO */
#define K1R_RD32(o)      (*(volatile uint32_t *)((g_k1r_dma.base) + (o)))
#define K1R_WR32(o,v)    (*(volatile uint32_t *)((g_k1r_dma.base) + (o)) = (v))

/* 通道索引: dma_chan_s 没有 id, 用 address 差推出 */
static int k1r_dma_chan_idx(FAR struct dma_chan_s *chan)
{
  return (int)(chan - &g_k1r_dma.chan[0]);
}

/* 把 0x4000_0000 窗口重定向到目标 DDR (关键, memcpy 前必做) */
static void k1r_dma_program_remap(void)
{
  irqstate_t flags = spin_lock_irqsave(&g_k1r_dma.lock);
  *(volatile uint32_t *)K1R_DMA_DDR_REMAP_BASE_REG = K1R_DMA_REMAP_UPPER_4G;
  spin_unlock_irqrestore(&g_k1r_dma.lock, flags);
}

/* 校验地址是否落在 DMA 窗口且不在禁址区 */
static int k1r_dma_check_addr(uintptr_t addr)
{
  if (addr < K1R_DMA_WIN_BASE ||
      addr >= (K1R_DMA_WIN_BASE + K1R_DMA_WIN_SIZE))
    {
      return -ENOTSUP;   /* 不在 0x40000000~0x4FFFFFFF 窗口 */
    }

  if (addr >= K1R_DMA_FORBID_LOW_START &&
      addr < K1R_DMA_FORBID_LOW_END)
    {
      return -EINVAL;    /* 禁址区 */
    }

  return OK;
}

/* --- config: direction/width -> CCR --- */
static int k1r_dma_config(FAR struct dma_chan_s *chan,
                          FAR const struct dma_config_s *cfg)
{
  uint32_t ccr = 0;
  uint32_t smode, dmode;

  DEBUGASSERT(chan != NULL && cfg != NULL);

  switch (cfg->direction)
    {
      case DMA_MEM_TO_MEM:
        smode = K1R_DMA_CCR_SMODE_MEM;
        dmode = K1R_DMA_CCR_DMODE_MEM;
        break;
      case DMA_MEM_TO_DEV:
        smode = K1R_DMA_CCR_SMODE_MEM;
        dmode = K1R_DMA_CCR_DMODE_FIFO;
        ccr |= K1R_DMA_CCR_REQ_EN;    /* FIFO 用 dma_req 发起 */
        break;
      case DMA_DEV_TO_MEM:
        smode = K1R_DMA_CCR_SMODE_FIFO;
        dmode = K1R_DMA_CCR_DMODE_MEM;
        ccr |= K1R_DMA_CCR_REQ_EN;
        break;
      default:
        return -EINVAL;
    }

  /* src/dst width: 1->8bit, 2->16bit, 4->32bit (bytes) */
  switch (cfg->src_width)
    {
      case 1: ccr |= K1R_DMA_CCR_SSIZE_8BIT;  break;
      case 2: ccr |= K1R_DMA_CCR_SSIZE_16BIT; break;
      case 4: ccr |= K1R_DMA_CCR_SSIZE_32BIT; break;
      default: ccr |= K1R_DMA_CCR_SSIZE_32BIT; break;
    }
  switch (cfg->dst_width)
    {
      case 1: ccr |= K1R_DMA_CCR_DSIZE_8BIT;  break;
      case 2: ccr |= K1R_DMA_CCR_DSIZE_16BIT; break;
      case 4: ccr |= K1R_DMA_CCR_DSIZE_32BIT; break;
      default: ccr |= K1R_DMA_CCR_DSIZE_32BIT; break;
    }

  ccr |= smode | dmode;

  /* 存 dccr 到每个通道: 这里用 chan->ops 无法存, 用 priv->active 标志占位。
   * 实际我们把 dccr 缓存在 g_k1r_dma.priv[idx] 之外需额外字段 —— 为简化,
   * 直接写 CCR (后续 start 会 RMW 置 CH_EN)。 */
  K1R_WR32(K1R_DMA_CCR(k1r_dma_chan_idx(chan)), ccr & ~K1R_DMA_CCR_CH_EN);
  return OK;
}

/* --- start: 发起单次线性传输 (memcpy) --- */
static int k1r_dma_start(FAR struct dma_chan_s *chan,
                         dma_callback_t callback, FAR void *arg,
                         uintptr_t dst, uintptr_t src, size_t len)
{
  int idx = k1r_dma_chan_idx(chan);
  int ret;

  DEBUGASSERT(chan != NULL);

  if (len == 0 || len > K1R_DMA_MAX_BYTES)
    {
      return -EINVAL;
    }

  if ((ret = k1r_dma_check_addr(dst)) < 0)
    {
      return ret;
    }
  if ((ret = k1r_dma_check_addr(src)) < 0)
    {
      return ret;
    }

  /* 1. 重定向 DMA 窗口到目标 DDR (关键) */
  k1r_dma_program_remap();

  /* 2. 写源/目的/长度 */
  K1R_WR32(K1R_DMA_SAR(idx), (uint32_t)src);
  K1R_WR32(K1R_DMA_DAR(idx), (uint32_t)dst);
  K1R_WR32(K1R_DMA_CNTR(idx), (uint32_t)len);

  /* 3. 突发: 64B + INCR */
  K1R_WR32(K1R_DMA_BLR(idx), K1R_DMA_BLR_BURST64);
  K1R_WR32(K1R_DMA_BTYPE(idx), K1R_DMA_BTYPE_INCR);

  /* 4. 软件发起: RSSR=0, CCR|=CH_EN, 清 DIMR 位开中断 */
  K1R_WR32(K1R_DMA_RSSR(idx), 0);
  K1R_WR32(K1R_DMA_CCR(idx),
           K1R_RD32(K1R_DMA_CCR(idx)) | K1R_DMA_CCR_CH_EN);
  K1R_WR32(K1R_DMA_DIMR, K1R_RD32(K1R_DMA_DIMR) & ~(1U << idx));

  /* 5. 记录回调 */
  g_k1r_dma.priv[idx].callback = callback;
  g_k1r_dma.priv[idx].arg      = arg;
  g_k1r_dma.priv[idx].active   = true;

  return OK;
}

static int k1r_dma_stop(FAR struct dma_chan_s *chan)
{
  int idx = k1r_dma_chan_idx(chan);
  K1R_WR32(K1R_DMA_CCR(idx), K1R_RD32(K1R_DMA_CCR(idx)) & ~K1R_DMA_CCR_CH_EN);
  K1R_WR32(K1R_DMA_DIMR, K1R_RD32(K1R_DMA_DIMR) | (1U << idx));
  g_k1r_dma.priv[idx].active = false;
  return OK;
}

static int k1r_dma_pause(FAR struct dma_chan_s *chan)
{
  int idx = k1r_dma_chan_idx(chan);
  K1R_WR32(K1R_DMA_CCR(idx), K1R_RD32(K1R_DMA_CCR(idx)) & ~K1R_DMA_CCR_CH_EN);
  return OK;
}

static int k1r_dma_resume(FAR struct dma_chan_s *chan)
{
  int idx = k1r_dma_chan_idx(chan);
  K1R_WR32(K1R_DMA_CCR(idx), K1R_RD32(K1R_DMA_CCR(idx)) | K1R_DMA_CCR_CH_EN);
  return OK;
}

static size_t k1r_dma_residual(FAR struct dma_chan_s *chan)
{
  int idx = k1r_dma_chan_idx(chan);
  return (size_t)(K1R_RD32(K1R_DMA_TRSFCNT(idx)) & K1R_DMA_BYTES_MSK);
}

static const struct dma_ops_s g_k1r_dma_ops =
{
  .config   = k1r_dma_config,
  .start    = k1r_dma_start,
  .stop     = k1r_dma_stop,
  .pause    = k1r_dma_pause,
  .resume   = k1r_dma_resume,
  .residual = k1r_dma_residual,
};

static FAR struct dma_chan_s *
k1r_dma_getchan(FAR struct dma_dev_s *dev, unsigned int ident)
{
  DEBUGASSERT(dev != NULL);
  if (ident >= K1R_AHBDMA_NCHAN)
    {
      return NULL;
    }
  return &g_k1r_dma.chan[ident];
}

static void k1r_dma_putchan(FAR struct dma_dev_s *dev,
                            FAR struct dma_chan_s *chan)
{
  DEBUGASSERT(dev != NULL && chan != NULL);
  k1r_dma_stop(chan);
}

/* --- 中断处理: 扫 DMA_SR, W1C, 调回调 --- */
static int k1r_dma_irqhandler(int irq, FAR void *context, FAR void *arg)
{
  uint32_t sr = K1R_RD32(K1R_DMA_SR);
  int i;

  for (i = 0; i < K1R_AHBDMA_NCHAN; i++)
    {
      if (sr & (1U << i))
        {
          K1R_WR32(K1R_DMA_SR, (1U << i));   /* W1C 清 */
          if (g_k1r_dma.priv[i].active && g_k1r_dma.priv[i].callback)
            {
              g_k1r_dma.priv[i].callback(&g_k1r_dma.chan[i],
                                         g_k1r_dma.priv[i].arg, OK);
              g_k1r_dma.priv[i].active = false;
            }
        }
    }
  return OK;
}

/* 上层入口: 拿到 dma_dev */
FAR struct dma_dev_s *k1r_dma_getdev(void)
{
  return &g_k1r_dma.dev;
}

/* 芯片启动初始化 (弱符号覆盖, riscv_initialize.c 调用) */
void riscv_dma_initialize(void)
{
  int n;

  g_k1r_dma.base       = K1R_AHBDMA_BASE;
  g_k1r_dma.dev.get_chan = k1r_dma_getchan;
  g_k1r_dma.dev.put_chan = k1r_dma_putchan;
  spin_initialize(&g_k1r_dma.lock, SPIN_UNLOCKED);

  for (n = 0; n < K1R_AHBDMA_NCHAN; n++)
    {
      g_k1r_dma.chan[n].ops = &g_k1r_dma_ops;
      g_k1r_dma.priv[n].active = false;
    }

  /* 使能 DMA 全局 */
  K1R_WR32(K1R_DMA_DCR, K1R_DMA_DCR_EN);

  /* 装中断 (注: 源号按 ECLIC 映射核对, K1R_DMA_IRQ) */
  irq_attach(K1R_DMA_IRQ, k1r_dma_irqhandler, NULL);
  up_enable_irq(K1R_DMA_IRQ);

  dminfo("k1r_dma: AHBDMA @%08lx, 16ch, irq %d\\n",
         (unsigned long)g_k1r_dma.base, K1R_DMA_IRQ);
}

#endif /* CONFIG_K1R_DMA */
