#ifdef CONFIG_K1R_DMA_SELFTEST
#define K1R_DMA_TEST_LEN 1024
int k1r_dma_selftest(void)
{
  struct dma_config_s cfg;
  struct dma_chan_s *chan;
  volatile uint8_t *src, *dst;
  volatile int done = 0;
  uint32_t i;
  int ret = -1;
  uintptr_t base = CONFIG_K1R_DMA_TEST_ADDR;

  src = (volatile uint8_t *)base;
  dst = (volatile uint8_t *)(base + K1R_DMA_TEST_LEN + 0x1000);  /* within window */
  chan = DMA_GET_CHAN(k1r_dma_getdev(), 0);
  if (!chan) return -1;

  /* fill src with pattern */
  for (i = 0; i < K1R_DMA_TEST_LEN; i++) src[i] = (uint8_t)(i & 0xff);

  memset(&cfg, 0, sizeof(cfg));
  cfg.direction = DMA_MEM_TO_MEM;
  cfg.src_width = 4; cfg.dst_width = 4;
  DMA_CONFIG(chan, &cfg);

  ret = DMA_START(chan, k1r_dma_selftest_cb, &done, (uintptr_t)dst, (uintptr_t)src, K1R_DMA_TEST_LEN);
  if (ret < 0) { printf("K1R DMA selftest: start fail %d\n", ret); return ret; }
  /* wait (poll, since we're in boot context; the IRQ callback sets done) */
  i = 0;
  while (!done && i++ < 100000) ;
  if (!done) { printf("K1R DMA selftest: timeout\n"); return -2; }

  /* compare */
  ret = 0;
  for (i = 0; i < K1R_DMA_TEST_LEN; i++)
    if (src[i] != dst[i]) { ret = -3; break; }

  printf("K1R DMA selftest: %s\n", (ret==0)?"PASS":"FAIL");
  DMA_PUT_CHAN(k1r_dma_getdev(), chan);
  return ret;
}
#endif
