}

static int k1r_set_callback(struct rptun_dev_s *dev, rptun_callback_t cb, void *arg)
{
  struct k1_rptun_dev_s *priv = as_k1r(dev);
  priv->callback = cb;
  priv->arg      = arg;
  return 0;
}

static const struct rptun_ops_s g_k1_rptun_ops =
{
  .get_cpuname       = k1r_get_cpuname,
  .get_resource      = k1r_get_resource,
  .is_autostart      = k1r_is_autostart,
  .is_master         = k1r_is_master,
  .start             = k1r_start,
  .stop              = k1r_stop,
  .notify            = k1r_notify,
  .register_callback = k1r_set_callback,
};

/* AP -> RCPU 的 kick: 读 ipc_iir, 清 ipc_icr, 调 rptun callback */
static int k1r_mailbox_irq(int irq, void *context, void *arg)
{
  struct k1_rptun_dev_s *priv = &g_rptun_dev;
  uint32_t status = *(volatile uint32_t *)(K1R_MAILBOX_BASE + K1R_MBOX_IIR);
  int i;

  UNUSED(irq);
  UNUSED(context);
  UNUSED(arg);

  for (i = 0; i < K1R_MAILBOX_CHAN_MAX; i++)
    {
      if (status & (1UL << i))
        {
          k1r_mailbox_clear(i);
        }
    }

  if (priv->callback)
    {
      priv->callback(priv->arg, RPTUN_NOTIFY_ALL);
    }

  return OK;
}

int k1_rptun_init(const char *peername)
{
  struct k1_rptun_dev_s *dev = &g_rptun_dev;
  int ret = OK;

  memset(dev, 0, sizeof(*dev));

#ifdef CONFIG_K1R_RPTUN_MASTER
  dev->master = true;
#else
  dev->master = false;   /* RCPU 是 remote */
#endif

