/* 校验地址是否落在 DMA 窗口且不在禁址区 */
static int k1r_dma_check_addr(uintptr_t addr)
{
  if (addr < K1R_DMA_WIN_BASE ||
      addr >= (K1R_DMA_WIN_BASE + K1R_DMA_WIN_SIZE))
    {
      return -ENOTSUP;   /* 不在 0x40000000~0x4FFFFFFF 窗口 */
    }

  if (addr >= K1R_DMA_FORBID_LOW_START &&
      addr < K1R_DMA_FORBID_LOW_END)
    {
      return -EINVAL;    /* 禁址区 */
    }

  return OK;
}

/* --- config: direction/width -> CCR --- */
static int k1r_dma_config(FAR struct dma_chan_s *chan,
                          FAR const struct dma_config_s *cfg)
{
  uint32_t ccr = 0;
  uint32_t smode, dmode;

  DEBUGASSERT(chan != NULL && cfg != NULL);

  switch (cfg->direction)
    {
      case DMA_MEM_TO_MEM:
        smode = K1R_DMA_CCR_SMODE_MEM;
        dmode = K1R_DMA_CCR_DMODE_MEM;
        break;
      case DMA_MEM_TO_DEV:
        smode = K1R_DMA_CCR_SMODE_MEM;
        dmode = K1R_DMA_CCR_DMODE_FIFO;
        ccr |= K1R_DMA_CCR_REQ_EN;    /* FIFO 用 dma_req 发起 */
        break;
      case DMA_DEV_TO_MEM:
        smode = K1R_DMA_CCR_SMODE_FIFO;
        dmode = K1R_DMA_CCR_DMODE_MEM;
        ccr |= K1R_DMA_CCR_REQ_EN;
        break;
      default:
        return -EINVAL;
    }

  /* src/dst width: 1->8bit, 2->16bit, 4->32bit (bytes) */
  switch (cfg->src_width)
    {
      case 1: ccr |= K1R_DMA_CCR_SSIZE_8BIT;  break;
      case 2: ccr |= K1R_DMA_CCR_SSIZE_16BIT; break;
      case 4: ccr |= K1R_DMA_CCR_SSIZE_32BIT; break;
      default: ccr |= K1R_DMA_CCR_SSIZE_32BIT; break;
    }
  switch (cfg->dst_width)
    {
      case 1: ccr |= K1R_DMA_CCR_DSIZE_8BIT;  break;
      case 2: ccr |= K1R_DMA_CCR_DSIZE_16BIT; break;
      case 4: ccr |= K1R_DMA_CCR_DSIZE_32BIT; break;
      default: ccr |= K1R_DMA_CCR_DSIZE_32BIT; break;
    }

  ccr |= smode | dmode;

  /* 存 dccr 到每个通道: 这里用 chan->ops 无法存, 用 priv->active 标志占位。
   * 实际我们把 dccr 缓存在 g_k1r_dma.priv[idx] 之外需额外字段 —— 为简化,
   * 直接写 CCR (后续 start 会 RMW 置 CH_EN)。 */
  K1R_WR32(K1R_DMA_CCR(k1r_dma_chan_idx(chan)), ccr & ~K1R_DMA_CCR_CH_EN);
  return OK;
}

