/* --- start: 发起单次线性传输 (memcpy) --- */
static int k1r_dma_start(FAR struct dma_chan_s *chan,
                         dma_callback_t callback, FAR void *arg,
                         uintptr_t dst, uintptr_t src, size_t len)
{
  int idx = k1r_dma_chan_idx(chan);
  int ret;

  DEBUGASSERT(chan != NULL);

  if (len == 0 || len > K1R_DMA_MAX_BYTES)
    {
      return -EINVAL;
    }

  if ((ret = k1r_dma_check_addr(dst)) < 0)
    {
      return ret;
    }
  if ((ret = k1r_dma_check_addr(src)) < 0)
    {
      return ret;
    }

  /* 1. 重定向 DMA 窗口到目标 DDR (关键) */
  k1r_dma_program_remap();

  /* 2. 写源/目的/长度 */
  K1R_WR32(K1R_DMA_SAR(idx), (uint32_t)src);
  K1R_WR32(K1R_DMA_DAR(idx), (uint32_t)dst);
  K1R_WR32(K1R_DMA_CNTR(idx), (uint32_t)len);

  /* 3. 突发: 64B + INCR */
  K1R_WR32(K1R_DMA_BLR(idx), K1R_DMA_BLR_BURST64);
  K1R_WR32(K1R_DMA_BTYPE(idx), K1R_DMA_BTYPE_INCR);

  /* 4. 软件发起: RSSR=0, CCR|=CH_EN, 清 DIMR 位开中断 */
  K1R_WR32(K1R_DMA_RSSR(idx), 0);
  K1R_WR32(K1R_DMA_CCR(idx),
           K1R_RD32(K1R_DMA_CCR(idx)) | K1R_DMA_CCR_CH_EN);
  K1R_WR32(K1R_DMA_DIMR, K1R_RD32(K1R_DMA_DIMR) & ~(1U << idx));

  /* 5. 记录回调 */
  g_k1r_dma.priv[idx].callback = callback;
  g_k1r_dma.priv[idx].arg      = arg;
  g_k1r_dma.priv[idx].active   = true;

