36: /* 每通道私有状态 (callback/arg 由 dma_chan_s 之外按 ident 索引) */
37: struct k1r_dma_chanpriv_s
38: {
39:   dma_callback_t callback;
40:   FAR void      *arg;
41:   bool           active;
42: };
43: 
44: struct k1r_dma_dev_s
45: {
46:   struct dma_dev_s           dev;   /* 必须首个, 用户拿到的就是它 */
47:   struct dma_chan_s          chan[K1R_AHBDMA_NCHAN];
48:   struct k1r_dma_chanpriv_s  priv[K1R_AHBDMA_NCHAN];
49:   spinlock_t                 lock;
50:   uintptr_t                  base;
51: };
52: 
53: static struct k1r_dma_dev_s g_k1r_dma;
54: 
55: #define K1R_GETPRIV(ch)  (&g_k1r_dma.priv[(ch)])
56: 
57: /* 存取 MMIO */
58: #define K1R_RD32(o)      (*(volatile uint32_t *)((g_k1r_dma.base) + (o)))
59: #define K1R_WR32(o,v)    (*(volatile uint32_t *)((g_k1r_dma.base) + (o)) = (v))
60: 
61: /* 通道索引: dma_chan_s 没有 id, 用 address 差推出 */
62: static int k1r_dma_chan_idx(FAR struct dma_chan_s *chan)
63: {
64:   return (int)(chan - &g_k1r_dma.chan[0]);
65: }
66: 
67: /* 把 0x4000_0000 窗口重定向到目标 DDR (关键, memcpy 前必做) */
68: static void k1r_dma_program_remap(void)
69: {
70:   irqstate_t flags = spin_lock_irqsave(&g_k1r_dma.lock);
71:   *(volatile uint32_t *)K1R_DMA_DDR_REMAP_BASE_REG = K1R_DMA_REMAP_UPPER_4G;
72:   spin_unlock_irqrestore(&g_k1r_dma.lock, flags);
73: }
74: 
75: /* 校验物理地址是否落在 DMA 禁址区 (低区 SRAM / 高区 AUD 外设) */
76: static int k1r_dma_check_addr(uintptr_t addr)
77: {
78:   if ((addr >= K1R_DMA_FORBID_LOW_START && addr < K1R_DMA_FORBID_LOW_END) ||
79:       (addr >= K1R_DMA_FORBID_HIGH_START && addr < K1R_DMA_FORBID_HIGH_END))
80:     {
81:       return -EINVAL;    /* DMA 禁址区 */
82:     }
83: 
84:   return OK;
85: }
