87: /* --- config: direction/width -> CCR --- */
88: static int k1r_dma_config(FAR struct dma_chan_s *chan,
89:                           FAR const struct dma_config_s *cfg)
90: {
91:   uint32_t ccr = 0;
92:   uint32_t smode, dmode;
93: 
94:   DEBUGASSERT(chan != NULL && cfg != NULL);
95: 
96:   switch (cfg->direction)
97:     {
98:       case DMA_MEM_TO_MEM:
99:         smode = K1R_DMA_CCR_SMODE_MEM;
100:         dmode = K1R_DMA_CCR_DMODE_MEM;
101:         break;
102:       case DMA_MEM_TO_DEV:
103:         smode = K1R_DMA_CCR_SMODE_MEM;
104:         dmode = K1R_DMA_CCR_DMODE_FIFO;
105:         ccr |= K1R_DMA_CCR_REQ_EN;    /* FIFO 用 dma_req 发起 */
106:         break;
107:       case DMA_DEV_TO_MEM:
108:         smode = K1R_DMA_CCR_SMODE_FIFO;
109:         dmode = K1R_DMA_CCR_DMODE_MEM;
110:         ccr |= K1R_DMA_CCR_REQ_EN;
111:         break;
112:       default:
113:         return -EINVAL;
114:     }
115: 
116:   /* src/dst width: 1->8bit, 2->16bit, 4->32bit (bytes) */
117:   switch (cfg->src_width)
118:     {
119:       case 1: ccr |= K1R_DMA_CCR_SSIZE_8BIT;  break;
120:       case 2: ccr |= K1R_DMA_CCR_SSIZE_16BIT; break;
121:       case 4: ccr |= K1R_DMA_CCR_SSIZE_32BIT; break;
122:       default: ccr |= K1R_DMA_CCR_SSIZE_32BIT; break;
123:     }
124:   switch (cfg->dst_width)
125:     {
126:       case 1: ccr |= K1R_DMA_CCR_DSIZE_8BIT;  break;
127:       case 2: ccr |= K1R_DMA_CCR_DSIZE_16BIT; break;
128:       case 4: ccr |= K1R_DMA_CCR_DSIZE_32BIT; break;
129:       default: ccr |= K1R_DMA_CCR_DSIZE_32BIT; break;
130:     }
131: 
132:   ccr |= smode | dmode;
133: 
134:   /* 存 dccr 到每个通道: 这里用 chan->ops 无法存, 用 priv->active 标志占位。
135:    * 实际我们把 dccr 缓存在 g_k1r_dma.priv[idx] 之外需额外字段 —— 为简化,
136:    * 直接写 CCR (后续 start 会 RMW 置 CH_EN)。 */
137:   K1R_WR32(K1R_DMA_CCR(k1r_dma_chan_idx(chan)), ccr & ~K1R_DMA_CCR_CH_EN);
138:   return OK;
139: }
140: 
141: /* --- start: 发起单次线性传输 (memcpy) --- */
142: static int k1r_dma_start(FAR struct dma_chan_s *chan,
143:                          dma_callback_t callback, FAR void *arg,
144:                          uintptr_t dst, uintptr_t src, size_t len)
145: {
146:   int idx = k1r_dma_chan_idx(chan);
147:   int ret;
148: 
149:   DEBUGASSERT(chan != NULL);
150: 
151:   if (len == 0 || len > K1R_DMA_MAX_BYTES)
152:     {
153:       return -EINVAL;
154:     }
155: 
156:   if ((ret = k1r_dma_check_addr(dst)) < 0)
157:     {
158:       return ret;
159:     }
160:   if ((ret = k1r_dma_check_addr(src)) < 0)
161:     {
162:       return ret;
163:     }
164: 
165:   /* 1. 重定向 DMA 窗口到目标 DDR (关键) */
166:   k1r_dma_program_remap();
167: 
168:   /* 2. 物理地址 -> DMA 窗口地址 (0x40000000 + (phys & 0x0FFFFFFF)), 再写 SAR/DAR/CNTR */
169:   {
170:     uint32_t dma_src = K1R_DMA_WIN_BASE + ((uint32_t)src & K1R_DMA_WIN_MASK);
171:     uint32_t dma_dst = K1R_DMA_WIN_BASE + ((uint32_t)dst & K1R_DMA_WIN_MASK);
172:     K1R_WR32(K1R_DMA_SAR(idx), dma_src);
173:     K1R_WR32(K1R_DMA_DAR(idx), dma_dst);
174:   }
175:   K1R_WR32(K1R_DMA_CNTR(idx), (uint32_t)len);
176: 
177:   /* 3. 突发: 64B + INCR */
178:   K1R_WR32(K1R_DMA_BLR(idx), K1R_DMA_BLR_BURST64);
179:   K1R_WR32(K1R_DMA_BTYPE(idx), K1R_DMA_BTYPE_INCR);
180: 
181:   /* 4. 软件发起: RSSR=0, CCR|=CH_EN, 清 DIMR 位开中断 */
182:   K1R_WR32(K1R_DMA_RSSR(idx), 0);
183:   K1R_WR32(K1R_DMA_CCR(idx),
184:            K1R_RD32(K1R_DMA_CCR(idx)) | K1R_DMA_CCR_CH_EN);
185:   K1R_WR32(K1R_DMA_DIMR, K1R_RD32(K1R_DMA_DIMR) & ~(1U << idx));
186: 
187:   /* 5. 记录回调 */
188:   g_k1r_dma.priv[idx].callback = callback;
189:   g_k1r_dma.priv[idx].arg      = arg;
190:   g_k1r_dma.priv[idx].active   = true;
191: 
192:   return OK;
193: }
194: 
195: static int k1r_dma_stop(FAR struct dma_chan_s *chan)
196: {
197:   int idx = k1r_dma_chan_idx(chan);
198:   K1R_WR32(K1R_DMA_CCR(idx), K1R_RD32(K1R_DMA_CCR(idx)) & ~K1R_DMA_CCR_CH_EN);
199:   K1R_WR32(K1R_DMA_DIMR, K1R_RD32(K1R_DMA_DIMR) | (1U << idx));
200:   g_k1r_dma.priv[idx].active = false;
201:   return OK;
202: }
203: 
204: static int k1r_dma_pause(FAR struct dma_chan_s *chan)
205: {
206:   int idx = k1r_dma_chan_idx(chan);
207:   K1R_WR32(K1R_DMA_CCR(idx), K1R_RD32(K1R_DMA_CCR(idx)) & ~K1R_DMA_CCR_CH_EN);
208:   return OK;
209: }
210: 
211: static int k1r_dma_resume(FAR struct dma_chan_s *chan)
212: {
213:   int idx = k1r_dma_chan_idx(chan);
214:   K1R_WR32(K1R_DMA_CCR(idx), K1R_RD32(K1R_DMA_CCR(idx)) | K1R_DMA_CCR_CH_EN);
215:   return OK;
216: }
217: 
218: static size_t k1r_dma_residual(FAR struct dma_chan_s *chan)
219: {
220:   int idx = k1r_dma_chan_idx(chan);
221:   return (size_t)(K1R_RD32(K1R_DMA_TRSFCNT(idx)) & K1R_DMA_BYTES_MSK);
222: }
223: 
224: static const struct dma_ops_s g_k1r_dma_ops =
225: {
226:   .config   = k1r_dma_config,
227:   .start    = k1r_dma_start,
228:   .stop     = k1r_dma_stop,
229:   .pause    = k1r_dma_pause,
230:   .resume   = k1r_dma_resume,
231:   .residual = k1r_dma_residual,
232: };
233: 
234: static FAR struct dma_chan_s *
235: k1r_dma_getchan(FAR struct dma_dev_s *dev, unsigned int ident)
236: {
237:   DEBUGASSERT(dev != NULL);
238:   if (ident >= K1R_AHBDMA_NCHAN)
239:     {
240:       return NULL;
241:     }
242:   return &g_k1r_dma.chan[ident];
243: }
244: 
245: static void k1r_dma_putchan(FAR struct dma_dev_s *dev,
246:                             FAR struct dma_chan_s *chan)
247: {
248:   DEBUGASSERT(dev != NULL && chan != NULL);
249:   k1r_dma_stop(chan);
250: }
