252: /* --- 中断处理: 扫 DMA_SR, W1C, 调回调 --- */
253: static int k1r_dma_irqhandler(int irq, FAR void *context, FAR void *arg)
254: {
255:   uint32_t sr = K1R_RD32(K1R_DMA_SR);
256:   int i;
257: 
258:   for (i = 0; i < K1R_AHBDMA_NCHAN; i++)
259:     {
260:       if (sr & (1U << i))
261:         {
262:           K1R_WR32(K1R_DMA_SR, (1U << i));   /* W1C 清 */
263:           if (g_k1r_dma.priv[i].active && g_k1r_dma.priv[i].callback)
264:             {
265:               g_k1r_dma.priv[i].callback(&g_k1r_dma.chan[i],
266:                                          g_k1r_dma.priv[i].arg, OK);
267:               g_k1r_dma.priv[i].active = false;
268:             }
269:         }
270:     }
271:   return OK;
272: }
273: 
274: /* 上层入口: 拿到 dma_dev */
275: FAR struct dma_dev_s *k1r_dma_getdev(void)
276: {
277:   return &g_k1r_dma.dev;
278: }
