280: /* 芯片启动初始化 (弱符号覆盖, riscv_initialize.c 调用) */
281: void riscv_dma_initialize(void)
282: {
283:   int n;
284: 
285:   g_k1r_dma.base       = K1R_AHBDMA_BASE;
286:   g_k1r_dma.dev.get_chan = k1r_dma_getchan;
287:   g_k1r_dma.dev.put_chan = k1r_dma_putchan;
288:   spin_lock_init(&g_k1r_dma.lock);
289: 
290:   for (n = 0; n < K1R_AHBDMA_NCHAN; n++)
291:     {
292:       g_k1r_dma.chan[n].ops = &g_k1r_dma_ops;
293:       g_k1r_dma.priv[n].active = false;
294:     }
295: 
296:   /* 使能 DMA 全局 */
297:   K1R_WR32(K1R_DMA_DCR, K1R_DMA_DCR_EN);
298: 
299:   /* 装中断 (注: 源号按 ECLIC 映射核对, K1R_DMA_IRQ) */
300:   irq_attach(K1R_DMA_IRQ, k1r_dma_irqhandler, NULL);
301:   up_enable_irq(K1R_DMA_IRQ);
302: }
