132: static int spacemit_rproc_prepare(struct rproc *rproc)
133: {
134: 	struct spacemit_rproc *priv = rproc->priv;
135: 	struct device *dev = rproc->dev.parent;
136: 	struct device_node *np = dev->of_node;
137: 	struct of_phandle_iterator it;
138: 	struct rproc_mem_entry *mem;
139: 	struct reserved_mem *rmem;
140: 	u32 da;
141: 	int ret, index = 0;
142: 
143: 	/* de-assert the audio module */
144: 	reset_control_deassert(priv->core_rst);
145: 
146: 	/* open the clk & pm-switch using pm-domain framework */
147: 	dev_pm_qos_add_request(priv->dev, &greq, DEV_PM_QOS_MAX_FREQUENCY,
148: 			DEV_PM_QOS_CLK_GATE | DEV_PM_QOS_PM_DOMAIN_GATE);
149: 
150: 	/* enable the power-switch and the clk */
151: 	pm_runtime_get_sync(priv->dev);
152: 
153: 	priv->apb_clk_rate_default = clk_get_rate(priv->apb_clk);
154: 
155: 	/* set apb clk rate */
156: 	clk_set_rate(priv->apb_clk, priv->apb_clk_rate);
157: 
158: 	/* Register associated reserved memory regions */
159: 	of_phandle_iterator_init(&it, np, "memory-region", NULL, 0);
160: 	while (of_phandle_iterator_next(&it) == 0) {
161: 		rmem = of_reserved_mem_lookup(it.node);
162: 		if (!rmem) {
163: 			dev_err(&rproc->dev,
164: 				"unable to acquire memory-region\n");
165: 			return -EINVAL;
166: 		}
167: 
168: 		if (rmem->base > U64_MAX) {
169: 			dev_err(&rproc->dev,
170: 				"the rmem base is overflow\n");
171: 			return -EINVAL;
172: 		}
173: 
174: 		/* find the da */
175: 		ret = of_property_read_u32(it.node, "da_base", &da);
176: 		if (ret) {
177: 			/* no da_base; means that the da = dma */
178: 			da = rmem->base;
179: 		}
180: 
181: 		mem = rproc_mem_entry_init(dev, NULL,
182: 					   rmem->base,
183: 					   rmem->size, da,
184: 					   spacemit_rproc_mem_alloc,
185: 					   spacemit_rproc_mem_release,
186: 					   it.node->name);
187: 		if (!mem)
188: 			return -ENOMEM;
189: 
190: 		rproc_add_carveout(rproc, mem);
191: 		index++;
192: 	}
193: 
194: 	return 0;
195: }
