197: static const void *find_version_id_section(struct device *dev, const struct firmware *fw)
198: {
199: 	const void *shdr, *name_table_shdr;
200: 	int i;
201: 	const char *name_table;
202: 	const u8 *elf_data = (void *)fw->data;
203: 	u8 class = fw_elf_get_class(fw);
204: 	const void *ehdr = elf_data;
205: 	u16 shnum = elf_hdr_get_e_shnum(class, ehdr);
206: 	u32 elf_shdr_get_size = elf_size_of_shdr(class);
207: 	u16 shstrndx = elf_hdr_get_e_shstrndx(class, ehdr);
208: 
209: 	/* First, get the section header according to the elf class */
210: 	shdr = elf_data + elf_hdr_get_e_shoff(class, ehdr);
211: 	/* Compute name table section header entry in shdr array */
212: 	name_table_shdr = shdr + (shstrndx * elf_shdr_get_size);
213: 	/* Finally, compute the name table section address in elf */
214: 	name_table = elf_data + elf_shdr_get_sh_offset(class, name_table_shdr);
215: 
216: 	for (i = 0; i < shnum; i++, shdr += elf_shdr_get_size) {
217: 		u32 name = elf_shdr_get_sh_name(class, shdr);
218: 
219: 		if (strcmp(name_table + name, ".version_id_table"))
220: 			continue;
221: 
222: 		/* make sure we have the entire table */
223: 		return shdr;
224: 	}
225: 
226: 	return NULL;
227: }
