229: char *rproc_elf_find_version_id_table(struct rproc *rproc, const struct firmware *fw, u64 *sh_size_p)
230: {
231: 	const void *shdr;
232: 	u64 sh_addr, sh_size;
233: 	u8 class = fw_elf_get_class(fw);
234: 	struct device *dev = &rproc->dev;
235: 
236: 	shdr = find_version_id_section(&rproc->dev, fw);
237: 	if (!shdr)
238: 		return NULL;
239: 
240: 	sh_addr = elf_shdr_get_sh_addr(class, shdr);
241: 	sh_size = elf_shdr_get_sh_size(class, shdr);
242: 
243: 	if (!rproc_u64_fit_in_size_t(sh_size)) {
244: 		dev_err(dev, "size (%llx) does not fit in size_t type\n",
245: 			sh_size);
246: 		return NULL;
247: 	}
248: 
249: 	*sh_size_p = sh_size;
250: 
251: 	return (char *)sh_addr;
252: }
