const content = `/****************************************************************************
 * vendor/SpaceMiT/chips/k1-rcpu/k1_rptun.c
 *
 * SpacemiT K1 RCPU 的 rptun 传输 (RCPU = OpenAMP remote, AP(X60) = host/master)。
 *
 * 参考: arch/risc-v/src/k230/k230_rptun.c (NuttX OpenAMP rptun 模板)。
 *
 * K1 内存布局 (AP dts k1-x.dtsi + k1x-rproc.c，权威):
 *   - RCPU da = 物理 + 0x2ff00000 (DDR_REMAP_BASE=0x100000)。
 *   - vring0  da 0x30200000, vring1 da 0x30203000, vdev0buffer da 0x30206000,
 *     rsc_table da 0x302fc000 (资源表)。
 *   - kick = RCPU 邮箱 AON_IPC2AP 0xC088A000 写 ipc_isrw(0x08) = 1<<vqid; IRQ = 30。
 *   - 收 AP kick: 读 ipc_iir 低 0-3 新消息, 清 ipc_icr, 并回 ack(写 ipc_isrw 的 bit(i+4))。
 *
 * 需要 CONFIG_RPTUN (select RPMSG_VIRTIO + OPENAMP) + CONFIG_RPMSG。
 ****************************************************************************/

#include <nuttx/config.h>

#include <assert.h>
#include <debug.h>
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

#include <nuttx/arch.h>
#include <nuttx/irq.h>
#include <nuttx/list.h>
#include <nuttx/rptun/rptun.h>
#include <nuttx/rpmsg/rpmsg.h>
#include <nuttx/drivers/addrenv.h>

#include "hardware/k1r_mailbox.h"
#include "hardware/k1r_memorymap.h"

#ifdef CONFIG_K1R_RPTUN

#define rpinfo rpmsginfo
#define rpwarn rpmsgwarn
#define rperr  rpmsgerr

#define VRINGS         2
#define VRING_ALIGN    8
#define VRING_NR       8
#define VRING_SIZE     512

/* K1 AP dts 共享内存 da (RCPU 视角), 见 knowledge/porting/k1-rcpu-rpmsg-protocol.md */
#define K1R_VRING0_DA      0x30200000UL
#define K1R_VRING1_DA      0x30203000UL
#define K1R_VDEV_BUF_DA    0x30206000UL
#define K1R_RSC_BASE       K1R_RSC_TABLE_BASE   /* 0x302FC000 资源表 */

#define RPMSG_NAME_SIZE    32

struct k1_rptun_shmem_s
{
  struct rptun_rsc_s  rsc;
  uintptr_t           base;
};

struct k1_rptun_dev_s
{
  struct rptun_dev_s        rptun;
  bool                      master;
  char                      peername[RPMSG_NAME_SIZE];
  struct k1_rptun_shmem_s  *shmem;
  struct rptun_addrenv_s    addrenv[VRINGS + 1];
  rptun_callback_t          callback;
  void                     *arg;
};

static struct k1_rptun_dev_s g_rptun_dev;

#define SHMEM      ((struct k1_rptun_shmem_s *)K1R_RSC_BASE)
#define as_k1r(d)  container_of(d, struct k1_rptun_dev_s, rptun)

static const char *k1r_get_cpuname(struct rptun_dev_s *dev)
{
  return as_k1r(dev)->peername;
}

static const struct rptun_addrenv_s *k1r_get_addrenv(struct rptun_dev_s *dev)
{
  struct k1_rptun_dev_s *priv = as_k1r(dev);
  return priv->addrenv;
}

static struct resource_table *k1r_get_resource(struct rptun_dev_s *dev)
{
  struct k1_rptun_dev_s *priv = as_k1r(dev);
  struct rptun_rsc_s *rsc;

  if (priv->shmem == NULL)
    {
      priv->shmem = SHMEM;
    }

  rsc = &priv->shmem->rsc;

  if (priv->master)
    {
      /* master 负责初始化资源表 (spilit 到 AP/对端时才由 host 初始化;
       * 此处按 master=remote 调试保留, 正常 RCPU 走 remote 分支读宿主已建表)。
       * remote 分支: 资源表由 AP(dts rsc_table)写入, 这里直接读。 */
      rsc->rsc_tbl_hdr.ver         = 1;
      rsc->rsc_tbl_hdr.num         = 2;
      rsc->offset[0]               = offsetof(struct rptun_rsc_s, rpmsg_vdev);
      rsc->rpmsg_vdev.type         = RSC_VDEV;
      rsc->rpmsg_vdev.id           = VIRTIO_ID_RPMSG;
      rsc->rpmsg_vdev.dfeatures    = 1 << VIRTIO_RPMSG_F_NS;
      rsc->rpmsg_vdev.num_of_vrings = VRINGS;
      rsc->rpmsg_vring0.align      = VRING_ALIGN;
      rsc->rpmsg_vring0.num        = VRING_NR;
      rsc->rpmsg_vring0.notifyid   = 0;
      rsc->rpmsg_vring0.da         = K1R_VRING0_DA;
      rsc->rpmsg_vring1.align      = VRING_ALIGN;
      rsc->rpmsg_vring1.num        = VRING_NR;
      rsc->rpmsg_vring1.notifyid   = 1;
      rsc->rpmsg_vring1.da         = K1R_VRING1_DA;
      rsc->config.r2h_buf_size     = VRING_SIZE;
      rsc->config.h2r_buf_size     = VRING_SIZE;
      priv->shmem->base            = (uintptr_t)priv->shmem;
    }

  return &rsc->rsc_tbl_hdr;
}

static bool k1r_is_autostart(struct rptun_dev_s *dev)
{
  return true;
}

static bool k1r_is_master(struct rptun_dev_s *dev)
{
  return as_k1r(dev)->master;
}

static int k1r_start(struct rptun_dev_s *dev)
{
  return 0;
}

static int k1r_stop(struct rptun_dev_s *dev)
{
  return 0;
}

static int k1r_notify(struct rptun_dev_s *dev, uint32_t vqid)
{
  UNUSED(dev);
  k1r_mailbox_notify(vqid);   /* 写 isrw=1<<vqid kick AP */
  return 0;
}

static int k1r_set_callback(struct rptun_dev_s *dev, rptun_callback_t cb, void *arg)
{
  struct k1_rptun_dev_s *priv = as_k1r(dev);
  priv->callback = cb;
  priv->arg      = arg;
  return 0;
}

static const struct rptun_ops_s g_k1_rptun_ops =
{
  .get_cpuname       = k1r_get_cpuname,
  .get_addrenv       = k1r_get_addrenv,
  .get_resource      = k1r_get_resource,
  .is_autostart      = k1r_is_autostart,
  .is_master         = k1r_is_master,
  .start             = k1r_start,
  .stop              = k1r_stop,
  .notify            = k1r_notify,
  .register_callback = k1r_set_callback,
};

/* AP -> RCPU kick: 读 iir, 清 icr, 回 ack(写 isrw bit(i+4)), 调 callback */
static int k1r_mailbox_irq(int irq, void *context, void *arg)
{
  struct k1_rptun_dev_s *priv = &g_rptun_dev;
  uint32_t status = *(volatile uint32_t *)(K1R_MAILBOX_BASE + K1R_MBOX_IIR);
  int i;

  UNUSED(irq);
  UNUSED(context);
  UNUSED(arg);

  status &= 0x0f;   /* 低 0-3 = 新消息 (chan0-3) */

  for (i = 0; i < K1R_MAILBOX_CHAN_MAX; i++)
    {
      if (status & (1UL << i))
        {
          k1r_mailbox_clear(i);                                  /* 清 icr */
          /* 回 ack 给 AP: 写 isrw 的 bit(i+4) (tx ack 区) */
          *(volatile uint32_t *)(K1R_MAILBOX_BASE + K1R_MBOX_ISRW) =
              (1UL << (i + 4));
        }
    }

  if (priv->callback)
    {
      priv->callback(priv->arg, RPTUN_NOTIFY_ALL);
    }

  return OK;
}

int k1_rptun_init(const char *peername)
{
  struct k1_rptun_dev_s *dev = &g_rptun_dev;
  int ret = OK;

  memset(dev, 0, sizeof(*dev));

#ifdef CONFIG_K1R_RPTUN_MASTER
  dev->master = true;
#else
  dev->master = false;   /* RCPU 是 remote */
#endif

  /* addrenv: da == pa (no-MMU, RCPU CPU 直接用 da 访问共享内存)。
   * da 是 rsc_table da 段内的偏移地址 (OpenAMP 用 da 定位 vring/buffer)。
   * 由于 RCPU 无 MMU 且共享内存就在其 da 空间, 这里将 pa 与 da 设为一致。 */
  dev->addrenv[0].pa   = K1R_VRING0_DA;
  dev->addrenv[0].da   = K1R_VRING0_DA;
  dev->addrenv[0].size = 0x1000;
  dev->addrenv[1].pa   = K1R_VRING1_DA;
  dev->addrenv[1].da   = K1R_VRING1_DA;
  dev->addrenv[1].size = 0x1000;
  dev->addrenv[2].pa   = K1R_VDEV_BUF_DA;
  dev->addrenv[2].da   = K1R_VDEV_BUF_DA;
  dev->addrenv[2].size = 0xf6000;
  dev->addrenv[3].size = 0;   /* 终止 */

  ret = irq_attach(K1R_MAILBOX_IRQ, k1r_mailbox_irq, NULL);
  if (ret < 0)
    {
      rperr("k1r mailbox irq_attach failed %d\n", ret);
      return ret;
    }

  up_enable_irq(K1R_MAILBOX_IRQ);

  dev->rptun.ops = &g_k1_rptun_ops;
  strncpy(dev->peername, peername, sizeof(dev->peername) - 1);

  ret = rptun_initialize(&dev->rptun);
  if (ret < 0)
    {
      rperr("rptun_initialize failed %d!\n", ret);
      up_disable_irq(K1R_MAILBOX_IRQ);
      return ret;
    }

  return OK;
}

#endif /* CONFIG_K1R_RPTUN */
